import React, { useRef, useEffect } from 'react';
import { DatabaseService } from '../services/db';
import { generateUUID } from '../utils/uuid';
import { Note } from '../types';
import { useDispatch, useSelector } from 'react-redux';
import { Action, dispatchThenReload, State } from '../store';
import EditableNote from './EditableNote';
import { ThunkDispatch } from 'redux-thunk';
import { UnknownAction } from '@reduxjs/toolkit';

const AddNote: React.FC = () => {
    const { isAdding, content } = useSelector((state: State) => state.addingNote);

    const dispatch: ThunkDispatch<State, void, UnknownAction> = useDispatch();
    const containerRef = useRef<HTMLDivElement>(null);

    const saveNote = async (content: string) => {
        if (content.trim()) {
            const newNote: Note = {
                id: Date.now(),
                uuid: generateUUID(),
                created_at: new Date().toISOString(),
                updated_at: new Date().toISOString(),
                content: content,
                status: 0,
            };
            await DatabaseService.saveNote(newNote);
            dispatch(dispatchThenReload((dispatch, getState) => {
                dispatch(Action.setAddingNote({ content: '', isAdding: false }));
            }, (dispatch, getState) => {
                dispatch(Action.syncNotesThunk());
            }));
        }
    };

    const cancelAddNote = (content: string) => {
        dispatch(Action.setAddingNote({ content: content, isAdding: false }));
    };

    useEffect(() => {
        if (isAdding && containerRef.current) {
            // 给一个小延迟确保编辑器已经完全渲染
            setTimeout(() => {
                const textarea = containerRef.current?.querySelector('textarea');
                if (textarea) {
                    textarea.focus();
                }
            }, 100);
        }
    }, [isAdding]);

    return isAdding ? (
        <EditableNote
            initialContent={content}
            onSave={saveNote}
            onCancel={cancelAddNote}
            ref={containerRef}
        />
    ) : null;
};

export default AddNote;